  function buildKeyMap(playerConfig, playerNumber) {
    var defaultKeys = {
      up: playerNumber === 1 ? "ArrowUp" : "KeyI",
      down: playerNumber === 1 ? "ArrowDown" : "KeyK",
      left: playerNumber === 1 ? "ArrowLeft" : "KeyJ",
      right: playerNumber === 1 ? "ArrowRight" : "KeyL",
      start: playerNumber === 1 ? "Enter" : "KeyH",
      mode: playerNumber === 1 ? "KeyZ" : "KeyV",
      a: playerNumber === 1 ? "KeyA" : "KeyB",
      b: playerNumber === 1 ? "KeyS" : "KeyN",
      c: playerNumber === 1 ? "KeyD" : "KeyM",
      x: playerNumber === 1 ? "KeyQ" : "KeyU",
      y: playerNumber === 1 ? "KeyW" : "KeyO",
      z: playerNumber === 1 ? "KeyE" : "KeyP",
    }

    var config = playerConfig || defaultKeys
    var map = {}

    if (config.up) {
      map[config.up] = "UP"
    }
    if (config.down) {
      map[config.down] = "DOWN"
    }
    if (config.left) {
      map[config.left] = "LEFT"
    }
    if (config.right) {
      map[config.right] = "RIGHT"
    }
    if (config.start) {
      map[config.start] = "START"
    }
    if (config.mode) {
      map[config.mode] = "MODE"
    }
    if (config.a) {
      map[config.a] = "A"
    }
    if (config.b) {
      map[config.b] = "B"
    }
    if (config.c) {
      map[config.c] = "C"
    }
    if (config.x) {
      map[config.x] = "X"
    }
    if (config.y) {
      map[config.y] = "Y"
    }
    if (config.z) {
      map[config.z] = "Z"
    }

    return map
  }

