  function downloadStateGenesis() {
    try {
      if (!globals.window["GENESIS_GAME_BOOTED"]) {
        return
      }

      if (globals.window["GENESIS_PICO_STATE_SAVE"]()) {
        var statePtr = globals.window["GENESIS_PICO_GET_STATE_BUFFER"]()
        var stateSize = globals.window["GENESIS_PICO_GET_STATE_SIZE"]()

        if (statePtr && stateSize > 0) {
          var stateData = new Uint8Array(
            globals.window["GENESIS"].HEAPU8.buffer,
            statePtr,
            stateSize
          )
          var blob = new Blob([stateData], {
            type: "application/octet-stream",
          })

          var url = URL.createObjectURL(blob)
          var a = globals.document.createElement("a")
          a.href = url
          a.download = globals.window["GENESIS_GAME_NAME"] + ".state"

          globals.document.body.appendChild(a)
          a.click()
          globals.document.body.removeChild(a)
          URL.revokeObjectURL(url)
        }
      }
    } catch (error) {
      //
    }
  }

  globals.window["downloadStateGenesis"] = downloadStateGenesis

  function uploadStateGenesis() {
    try {
      if (!globals.window["GENESIS_GAME_BOOTED"]) {
        return
      }

      // drop the input used by the previous call, if the picker was cancelled
      // it is still hanging around in the DOM.
      if (
        globals.window["GENESIS_STATE_INPUT"] &&
        globals.window["GENESIS_STATE_INPUT"].parentNode
      ) {
        globals.window["GENESIS_STATE_INPUT"].parentNode.removeChild(
          globals.window["GENESIS_STATE_INPUT"]
        )
      }
      globals.window["GENESIS_STATE_INPUT"] = null

      var input = globals.document.createElement("input")
      input.type = "file"
      input.accept = ".state"
      input.style.display = "none"

      // the input must stay in the DOM while the native file picker is open.
      // on ios safari a detached input (and its change listener) can be
      // garbage collected while the page sits in the background behind the
      // picker, and then the change event never fires.
      document.getElementsByTagName("body")[0].appendChild(input)
      globals.window["GENESIS_STATE_INPUT"] = input

      input.addEventListener("change", function (event) {
        var file = event.target.files[0]
        if (!file) {
          return
        }

        var reader = new FileReader()
        reader.addEventListener("load", function (e) {
          try {
            var data = new Uint8Array(e.target.result)
            var size = data.length

            var bufPtr = globals.window["GENESIS_PICO_GET_STATE_LOAD_BUFFER"](size)
            if (!bufPtr) {
              return
            }

            globals.window["GENESIS"].HEAPU8.set(data, bufPtr)

            // the core rejected the state: leave the emulator untouched
            // rather than resetting audio for a load that never happened.
            if (!globals.window["GENESIS_PICO_STATE_LOAD"]()) {
              return
            }

            globals.window["GENESIS_NEXT_AUDIO_TIME"] = 0
            globals.window["GENESIS_AUDIO_START_TIME"] = null
          } catch (error) {
            //
          }
        })

        // the read itself failed (unreadable file, or an icloud file that
        // never finished downloading). the load handler never runs, so
        // release the input here instead of leaving it in the DOM until the
        // next call. there is no ui to report the failure through.
        reader.addEventListener("error", function () {
          if (input.parentNode) {
            input.parentNode.removeChild(input)
          }
          if (globals.window["GENESIS_STATE_INPUT"] === input) {
            globals.window["GENESIS_STATE_INPUT"] = null
          }
        })

        reader.readAsArrayBuffer(file)
      })

      input.click()
    } catch (error) {
      //
    }
  }

  globals.window["uploadStateGenesis"] = uploadStateGenesis

  function requestEmulatorFullscreenGenesis() {
    try {
      if (!globals.window["GENESIS_GAME_BOOTED"]) {
        return
      }

      var docEl = globals.document.getElementById(
        globals.window["GENESIS_CONTAINER"]
      )

      var requestFull =
        docEl.requestFullscreen ||
        docEl.mozRequestFullScreen ||
        docEl.webkitRequestFullscreen ||
        docEl.msRequestFullscreen

      var isFull =
        globals.document.fullscreenElement ||
        globals.document.mozFullScreenElement ||
        globals.document.webkitFullscreenElement ||
        globals.document.msFullscreenElement

      if (!isFull) {
        if (requestFull) {
          requestFull.call(docEl)
        }
      }
    } catch (err2) {
      //
    }
  }

  globals.window["requestEmulatorFullscreenGenesis"] =
    requestEmulatorFullscreenGenesis
